package com.camstream.mobile;
import android.app.*;import android.content.*;import android.graphics.PixelFormat;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;
public class FloatingControlsService extends Service {
 WindowManager wm;View panel;WindowManager.LayoutParams lp;
 @Override public void onCreate(){super.onCreate();if(!Settings.canDrawOverlays(this)){stopSelf();return;}wm=(WindowManager)getSystemService(WINDOW_SERVICE);panel=build();int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;lp=new WindowManager.LayoutParams(WindowManager.LayoutParams.WRAP_CONTENT,WindowManager.LayoutParams.WRAP_CONTENT,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.END;lp.x=20;lp.y=180;wm.addView(panel,lp);}
 View build(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(12,8,12,8);box.setBackgroundColor(0xEE171F32);TextView title=new TextView(this);title.setText("CAM STREAM");title.setTextColor(-1);box.addView(title);String[] labels={"STOP","HIDE"};for(String s:labels){Button b=new Button(this);b.setText(s);box.addView(b);b.setOnClickListener(v->{if(s.equals("STOP")){startService(new Intent(this,RecordingService.class).setAction(RecordingService.ACTION_STOP));}else{wm.removeView(panel);panel=null;stopSelf();}});}box.setOnTouchListener(new View.OnTouchListener(){float x,y;int ox,oy;public boolean onTouch(View v,android.view.MotionEvent e){if(e.getAction()==0){x=e.getRawX();y=e.getRawY();ox=lp.x;oy=lp.y;return true;}if(e.getAction()==2){lp.x=ox+(int)(x-e.getRawX());lp.y=oy+(int)(e.getRawY()-y);wm.updateViewLayout(panel,lp);return true;}return false;}});return box;}
 @Override public void onDestroy(){if(panel!=null)try{wm.removeView(panel);}catch(Exception ignored){}super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}
